=item * C<< $msg->database_config() >> / C<< $msg->database_config($value) >>

Type: C<Message> (L<Google::Cloud::Orchestration::Airflow::Service::V1::Environments::DatabaseConfig>)

Optional. The configuration settings for Cloud SQL instance used internally
