This field is supported for Cloud Composer environments in versions
composer-2.*.*-airflow-*.*.* and newer.

=item * C<< $msg->environment_size() >> / C<< $msg->environment_size($value) >>

Type: C<Enum> (L<Google::Cloud::Orchestration::Airflow::Service::V1::EnvironmentConfig::EnvironmentSize>)

Optional. The size of the Cloud Composer environment.

This field is supported for Cloud Composer environments in versions
composer-2.*.*-airflow-*.*.* and newer.

=item * C<< $msg->airflow_uri() >> / C<< $msg->airflow_uri($value) >>

Type: C<String>

Output only. The URI of the Apache Airflow Web UI hosted within this
environment (see [Airflow web
interface](/composer/docs/how-to/accessing/airflow-web-interface)).

=item * C<< $msg->airflow_byoid_uri() >> / C<< $msg->airflow_byoid_uri($value) >>

Type: C<String>

Output only. The 'bring your own identity' variant of the URI of the Apache
Airflow Web UI hosted within this environment, to be accessed with external
identities using workforce identity federation (see [Access environments
with workforce identity
federation](/composer/docs/composer-2/access-environments-with-workforce-identity-federation)).

=item * C<< $msg->master_authorized_networks_config() >> / C<< $msg->master_authorized_networks_config($value) >>

Type: C<Message> (L<Google::Cloud::Orchestration::Airflow::Service::V1::Environments::MasterAuthorizedNetworksConfig>)

Optional. The configuration options for GKE cluster master authorized
networks. By default master authorized networks feature is:
- in case of private environment: enabled with no external networks
allowlisted.
- in case of public environment: disabled.

=item * C<< $msg->recovery_config() >> / C<< $msg->recovery_config($value) >>

Type: C<Message> (L<Google::Cloud::Orchestration::Airflow::Service::V1::Environments::RecoveryConfig>)

