=head2 Google::Cloud::Orchestration::Airflow::Service::V1::Environments::MaintenanceWindow

The configuration settings for Cloud Composer maintenance window.
The following example:

```
   {
     "startTime":"2019-08-01T01:00:00Z"
     "endTime":"2019-08-01T07:00:00Z"
     "recurrence":"FREQ=WEEKLY;BYDAY=TU,WE"
   }
```

would define a maintenance window between 01 and 07 hours UTC during
each Tuesday and Wednesday.

Inherits from L<Protobuf::Message>.

=head3 Accessors

=over 4

=item * C<< $msg->start_time() >> / C<< $msg->start_time($value) >>

Type: C<Message> (L<Google::Protobuf::Timestamp::Timestamp>)

Required. Start time of the first recurrence of the maintenance window.

=item * C<< $msg->end_time() >> / C<< $msg->end_time($value) >>

Type: C<Message> (L<Google::Protobuf::Timestamp::Timestamp>)

Required. Maintenance window end time. It is used only to calculate the
duration of the maintenance window. The value for end-time must be in the
future, relative to `start_time`.

=item * C<< $msg->recurrence() >> / C<< $msg->recurrence($value) >>

Type: C<String>

Required. Maintenance window recurrence. Format is a subset of
[RFC-5545](https://tools.ietf.org/html/rfc5545) `RRULE`. The only allowed
values for `FREQ` field are `FREQ=DAILY` and `FREQ=WEEKLY;BYDAY=...`
Example values: `FREQ=WEEKLY;BYDAY=TU,WE`, `FREQ=DAILY`.

=back

=head2 Google::Cloud::Orchestration::Airflow::Service::V1::Environments::SoftwareConfig

Specifies the selection and configuration of software inside the environment.

Inherits from L<Protobuf::Message>.

=head3 Accessors

=over 4

=item * C<< $msg->image_version() >> / C<< $msg->image_version($value) >>

Type: C<String>

Optional. The version of the software running in the environment.
This encapsulates both the version of Cloud Composer functionality and the
version of Apache Airflow. It must match the regular expression
`composer-([0-9]+(\.[0-9]+\.[0-9]+(-preview\.[0-9]+)?)?|latest)-airflow-([0-9]+(\.[0-9]+(\.[0-9]+)?)?)`.
When used as input, the server also checks if the provided version is
supported and denies the request for an unsupported version.

The Cloud Composer portion of the image version is a full
[semantic version](https://semver.org), or an alias in the form of major
version number or `latest`. When an alias is provided, the server replaces
it with the current Cloud Composer version that satisfies the alias.

The Apache Airflow portion of the image version is a full semantic version
that points to one of the supported Apache Airflow versions, or an alias in
the form of only major or major.minor versions specified. When an alias is
provided, the server replaces it with the latest Apache Airflow version
that satisfies the alias and is supported in the given Cloud Composer
version.

In all cases, the resolved image version is stored in the same field.

See also [version
list](/composer/docs/concepts/versioning/composer-versions) and [versioning
overview](/composer/docs/concepts/versioning/composer-versioning-overview).

=item * C<< $msg->airflow_config_overrides() >> / C<< $msg->airflow_config_overrides($value) >>

Type: C<Message> (L<Google::Cloud::Orchestration::Airflow::Service::V1::Environments::SoftwareConfig::AirflowConfigOverridesEntry>)

Optional. Apache Airflow configuration properties to override.

Property keys contain the section and property names, separated by a
hyphen, for example "core-dags_are_paused_at_creation". Section names must
not contain hyphens ("-"), opening square brackets ("["),  or closing
square brackets ("]"). The property name must not be empty and must not
contain an equals sign ("=") or semicolon (";"). Section and property names
must not contain a period ("."). Apache Airflow configuration property
names must be written in
[snake_case](https://en.wikipedia.org/wiki/Snake_case). Property values can
contain any character, and can be written in any lower/upper case format.

Certain Apache Airflow configuration property values are
[blocked](/composer/docs/concepts/airflow-configurations),
and cannot be overridden.

=item * C<< $msg->pypi_packages() >> / C<< $msg->pypi_packages($value) >>

Type: C<Message> (L<Google::Cloud::Orchestration::Airflow::Service::V1::Environments::SoftwareConfig::PypiPackagesEntry>)

Optional. Custom Python Package Index (PyPI) packages to be installed in
the environment.

Keys refer to the lowercase package name such as "numpy"
and values are the lowercase extras and version specifier such as
"==1.12.0", "[devel,gcp_api]", or "[devel]>=1.8.2, <1.9.2". To specify a
package without pinning it to a version specifier, use the empty string as
the value.

=item * C<< $msg->env_variables() >> / C<< $msg->env_variables($value) >>

Type: C<Message> (L<Google::Cloud::Orchestration::Airflow::Service::V1::Environments::SoftwareConfig::EnvVariablesEntry>)

Optional. Additional environment variables to provide to the Apache Airflow
scheduler, worker, and webserver processes.

Environment variable names must match the regular expression
`[a-zA-Z_][a-zA-Z0-9_]*`. They cannot specify Apache Airflow
software configuration overrides (they cannot match the regular expression
`AIRFLOW__[A-Z0-9_]+__[A-Z0-9_]+`), and they cannot match any of the
following reserved names:

* `AIRFLOW_HOME`
* `C_FORCE_ROOT`
* `CONTAINER_NAME`
* `DAGS_FOLDER`
* `GCP_PROJECT`
* `GCS_BUCKET`
* `GKE_CLUSTER_NAME`
* `SQL_DATABASE`
* `SQL_INSTANCE`
* `SQL_PASSWORD`
* `SQL_PROJECT`
* `SQL_REGION`
* `SQL_USER`

=item * C<< $msg->python_version() >> / C<< $msg->python_version($value) >>

Type: C<String>

Optional. The major version of Python used to run the Apache Airflow
scheduler, worker, and webserver processes.

Can be set to '2' or '3'. If not specified, the default is '3'. Cannot be
updated.

This field is only supported for Cloud Composer environments in versions
composer-1.*.*-airflow-*.*.*. Environments in newer versions always use
Python major version 3.

=item * C<< $msg->scheduler_count() >> / C<< $msg->scheduler_count($value) >>

Type: C<Int32>

Optional. The number of schedulers for Airflow.

This field is supported for Cloud Composer environments in versions
composer-1.*.*-airflow-2.*.*.

=item * C<< $msg->cloud_data_lineage_integration() >> / C<< $msg->cloud_data_lineage_integration($value) >>

Type: C<Message> (L<Google::Cloud::Orchestration::Airflow::Service::V1::Environments::CloudDataLineageIntegration>)

Optional. The configuration for Cloud Data Lineage integration.

=item * C<< $msg->web_server_plugins_mode() >> / C<< $msg->web_server_plugins_mode($value) >>

Type: C<Enum> (L<Google::Cloud::Orchestration::Airflow::Service::V1::SoftwareConfig::WebServerPluginsMode>)

Optional. Whether or not the web server uses custom plugins.
If unspecified, the field defaults to `PLUGINS_ENABLED`.

This field is supported for Cloud Composer environments in versions
composer-3-airflow-*.*.*-build.* and newer.

=back

=head3 Enum: SoftwareConfig::WebServerPluginsMode

=over 4

=item * C<WEB_SERVER_PLUGINS_MODE_UNSPECIFIED> => C<0>

=item * C<PLUGINS_DISABLED> => C<1>

=item * C<PLUGINS_ENABLED> => C<2>

=back

=head2 Google::Cloud::Orchestration::Airflow::Service::V1::Environments::IPAllocationPolicy

Configuration for controlling how IPs are allocated in the
GKE cluster running the Apache Airflow software.

Inherits from L<Protobuf::Message>.

=head3 Accessors

=over 4

=item * C<< $msg->use_ip_aliases() >> / C<< $msg->use_ip_aliases($value) >>

Type: C<Bool>

Optional. Whether or not to enable Alias IPs in the GKE cluster.
If `true`, a VPC-native cluster is created.

This field is only supported for Cloud Composer environments in versions
composer-1.*.*-airflow-*.*.*. Environments in newer versions always use
