=head2 Google::Cloud::Orchestration::Airflow::Service::V1::Environments::Environment

An environment for running orchestration tasks.

Inherits from L<Protobuf::Message>.

=head3 Accessors

=over 4

=item * C<< $msg->name() >> / C<< $msg->name($value) >>

Type: C<String>

Identifier. The resource name of the environment, in the form:
"projects/{projectId}/locations/{locationId}/environments/{environmentId}"

EnvironmentId must start with a lowercase letter followed by up to 63
lowercase letters, numbers, or hyphens, and cannot end with a hyphen.

=item * C<< $msg->config() >> / C<< $msg->config($value) >>

Type: C<Message> (L<Google::Cloud::Orchestration::Airflow::Service::V1::Environments::EnvironmentConfig>)

Optional. Configuration parameters for this environment.

=item * C<< $msg->uuid() >> / C<< $msg->uuid($value) >>

Type: C<String>

Output only. The UUID (Universally Unique IDentifier) associated with this
environment. This value is generated when the environment is created.

=item * C<< $msg->state() >> / C<< $msg->state($value) >>

Type: C<Enum> (L<Google::Cloud::Orchestration::Airflow::Service::V1::Environment::State>)

The current state of the environment.

=item * C<< $msg->create_time() >> / C<< $msg->create_time($value) >>

Type: C<Message> (L<Google::Protobuf::Timestamp::Timestamp>)

Output only. The time at which this environment was created.

=item * C<< $msg->update_time() >> / C<< $msg->update_time($value) >>

Type: C<Message> (L<Google::Protobuf::Timestamp::Timestamp>)

Output only. The time at which this environment was last modified.

=item * C<< $msg->labels() >> / C<< $msg->labels($value) >>

Type: C<Message> (L<Google::Cloud::Orchestration::Airflow::Service::V1::Environments::Environment::LabelsEntry>)

Optional. User-defined labels for this environment.
The labels map can contain no more than 64 entries. Entries of the labels
map are UTF8 strings that comply with the following restrictions:

* Keys must conform to regexp: [\p{Ll}\p{Lo}][\p{Ll}\p{Lo}\p{N}_-]{0,62}
* Values must conform to regexp:  [\p{Ll}\p{Lo}\p{N}_-]{0,63}
* Both keys and values are additionally constrained to be <= 128 bytes in
size.

=item * C<< $msg->satisfies_pzs() >> / C<< $msg->satisfies_pzs($value) >>

Type: C<Bool>

Output only. Reserved for future use.

=item * C<< $msg->satisfies_pzi() >> / C<< $msg->satisfies_pzi($value) >>

Type: C<Bool>

Output only. Reserved for future use.

=item * C<< $msg->storage_config() >> / C<< $msg->storage_config($value) >>

Type: C<Message> (L<Google::Cloud::Orchestration::Airflow::Service::V1::Environments::StorageConfig>)

Optional. Storage configuration for this environment.

=back

=head3 Enum: Environment::State

=over 4

=item * C<STATE_UNSPECIFIED> => C<0>

=item * C<CREATING> => C<1>

=item * C<RUNNING> => C<2>

=item * C<UPDATING> => C<3>

=item * C<DELETING> => C<4>

=item * C<ERROR> => C<5>

=back

=head2 Google::Cloud::Orchestration::Airflow::Service::V1::Environments::CheckUpgradeRequest

Request to check whether image upgrade will succeed.

Inherits from L<Protobuf::Message>.

=head3 Accessors

=over 4

=item * C<< $msg->environment() >> / C<< $msg->environment($value) >>

Type: C<String>

Required. The resource name of the environment to check upgrade for, in the
form:
"projects/{projectId}/locations/{locationId}/environments/{environmentId}"

=item * C<< $msg->image_version() >> / C<< $msg->image_version($value) >>

Type: C<String>

Optional. The version of the software running in the environment.
This encapsulates both the version of Cloud Composer functionality and the
version of Apache Airflow. It must match the regular expression
`composer-([0-9]+(\.[0-9]+\.[0-9]+(-preview\.[0-9]+)?)?|latest)-airflow-([0-9]+(\.[0-9]+(\.[0-9]+)?)?)`.
When used as input, the server also checks if the provided version is
supported and denies the request for an unsupported version.

The Cloud Composer portion of the image version is a full
[semantic version](https://semver.org), or an alias in the form of major
version number or `latest`. When an alias is provided, the server replaces
it with the current Cloud Composer version that satisfies the alias.

The Apache Airflow portion of the image version is a full semantic version
that points to one of the supported Apache Airflow versions, or an alias in
the form of only major or major.minor versions specified. When an alias is
provided, the server replaces it with the latest Apache Airflow version
that satisfies the alias and is supported in the given Cloud Composer
version.

In all cases, the resolved image version is stored in the same field.

See also [version
list](/composer/docs/concepts/versioning/composer-versions) and [versioning
overview](/composer/docs/concepts/versioning/composer-versioning-overview).

=back

=head2 Google::Cloud::Orchestration::Airflow::Service::V1::Environments::CheckUpgradeResponse

Message containing information about the result of an upgrade check
operation.

Inherits from L<Protobuf::Message>.

=head3 Accessors

=over 4

=item * C<< $msg->build_log_uri() >> / C<< $msg->build_log_uri($value) >>

Type: C<String>

