=item * C<< $msg->contains_pypi_modules_conflict() >> / C<< $msg->contains_pypi_modules_conflict($value) >>

Type: C<Enum> (L<Google::Cloud::Orchestration::Airflow::Service::V1::CheckUpgradeResponse::ConflictResult>)

Output only. Whether build has succeeded or failed on modules conflicts.

=item * C<< $msg->pypi_conflict_build_log_extract() >> / C<< $msg->pypi_conflict_build_log_extract($value) >>

Type: C<String>

Output only. Extract from a docker image build log containing information
about pypi modules conflicts.

=item * C<< $msg->image_version() >> / C<< $msg->image_version($value) >>

Type: C<String>

Composer image for which the build was happening.

=item * C<< $msg->pypi_dependencies() >> / C<< $msg->pypi_dependencies($value) >>

Type: C<Message> (L<Google::Cloud::Orchestration::Airflow::Service::V1::Environments::CheckUpgradeResponse::PypiDependenciesEntry>)

Pypi dependencies specified in the environment configuration, at the time
when the build was triggered.

=back

=head3 Enum: CheckUpgradeResponse::ConflictResult

=over 4

=item * C<CONFLICT_RESULT_UNSPECIFIED> => C<0>

=item * C<CONFLICT> => C<1>

=item * C<NO_CONFLICT> => C<2>

=back

=head2 Google::Cloud::Orchestration::Airflow::Service::V1::Environments::DataRetentionConfig

The configuration setting for Airflow database data retention mechanism.

Inherits from L<Protobuf::Message>.

